    public static IEnumerable<string> Keys => English.Keys;
    public static string? Pattern(string key) => English.GetValueOrDefault(key);
    public static string T(string key, object? arguments = null)
    {
        if (!English.TryGetValue(key, out var pattern)) return AdminText.Has(key) ? AdminText.T(key, arguments) : AppStrings.Get(key, fallback: key);
        var values = arguments as IReadOnlyDictionary<string, object?> ?? arguments?.GetType().GetProperties().ToDictionary(property => property.Name, property => property.GetValue(arguments)) ?? new Dictionary<string, object?>();
        return AdminText.Format(pattern, values);
    }
